//! JSON Schema of the `.surgery` header (`surgeon schema --kind surgery`).

use serde_json::Value;

use super::format::SurgeryHeader;

/// Draft-07 schema generated by schemars from [`SurgeryHeader`].
pub fn header_schema() -> Value {
    let settings = schemars::gen::SchemaSettings::draft07();
    let schema = settings
        .into_generator()
        .into_root_schema_for::<SurgeryHeader>();
    serde_json::to_value(schema).unwrap_or(Value::Null)
}
